<?php /** @var array $x @var array $requests @var array $assumptions */ $c = $x['c']; require __DIR__ . '/_tabs.php'; $edit = can('icaap.manage') && !$locked; $lateCut = date('Y-m-d', strtotime('-' . \App\Support\Icaap::LATE_DATA_DAYS . ' days')); ?>
<section class="card" id="requests"><h2><?= e(t('icaap.data_requests')) ?></h2><p class="muted"><?= e(t('icaap.data_requests_hint')) ?></p>
<div class="table-wrap"><table class="data"><thead><tr><th><?= e(t('icaap.provider')) ?></th><th><?= e(t('icaap.data_items')) ?></th><th><?= e(t('icaap.format')) ?></th><th><?= e(t('icaap.due_on')) ?></th><th><?= e(t('icaap.received_on')) ?></th></tr></thead><tbody>
<?php foreach ($requests as $q): $late = !$q['received_on'] && $q['due_on'] && $q['due_on'] < $lateCut; ?><tr><td><?= e($q['provider']) ?></td><td><?= e($q['data_items']) ?><?= $q['note'] ? '<br><span class="muted small">' . e($q['note']) . '</span>' : '' ?></td><td><?= e($q['format'] ?? '') ?></td>
<td colspan="2"><?php if ($edit): ?><form method="post" action="<?= e(url('icaap/' . $c['id'] . '/requests/' . $q['id'])) ?>" class="inline-form" novalidate><?= csrf_field() ?><input type="date" name="due_on" value="<?= e($q['due_on'] ?? '') ?>" aria-label="<?= e(t('icaap.due_on')) ?>"> <input type="date" name="received_on" value="<?= e($q['received_on'] ?? '') ?>" aria-label="<?= e(t('icaap.received_on')) ?>"> <input type="text" name="note" value="<?= e($q['note'] ?? '') ?>" placeholder="<?= e(t('rm.note')) ?>" aria-label="<?= e(t('rm.note')) ?>"> <button class="btn small" type="submit"><?= e(t('common.save')) ?></button></form>
<?php else: ?><?= e(fdate($q['due_on']) ?: '—') ?> · <?= e(fdate($q['received_on']) ?: '—') ?><?php endif; ?><?= $late ? ' <span class="badge danger">' . e(t('icaap.late')) . '</span>' : '' ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php if ($edit): ?><details><summary><strong><?= e(t('icaap.add_request')) ?></strong></summary><form method="post" action="<?= e(url('icaap/' . $c['id'] . '/requests')) ?>" class="form-grid" novalidate><?= csrf_field() ?>
<?= ff('text', 'provider', 'icaap.provider', '', ['required' => true]) ?><?= ff('textarea', 'data_items', 'icaap.data_items', '', ['required' => true, 'wide' => true]) ?><?= ff('date', 'data_date', 'icaap.data_date', $c['data_date']) ?><?= ff('text', 'format', 'icaap.format', 'Excel') ?><?= ff('date', 'due_on', 'icaap.due_on', '') ?>
<div class="field"><button class="btn" type="submit"><?= e(t('common.save')) ?></button></div></form></details><?php endif; ?></section>
<section class="card" id="assumptions"><h2><?= e(t('icaap.assumptions')) ?></h2><p class="muted"><?= e(t('icaap.assumptions_hint')) ?></p>
<div class="table-wrap"><table class="data"><thead><tr><th>#</th><th><?= e(t('icaap.stage')) ?></th><th><?= e(t('icaap.assumption')) ?></th><th><?= e(t('icaap.rationale')) ?></th><th><?= e(t('icaap.impact')) ?></th><th><?= e(t('icaap.made_by')) ?></th><th><?= e(t('icaap.approved_by')) ?></th></tr></thead><tbody>
<?php if (!$assumptions): ?><tr><td colspan="7" class="muted"><?= e(t('common.no_data')) ?></td></tr><?php endif; ?>
<?php foreach ($assumptions as $i => $a): ?><tr><td><?= $i + 1 ?></td><td><?= e($a['stage']) ?></td><td class="pre"><?= e($a['assumption']) ?></td><td class="pre"><?= e($a['rationale'] ?? '') ?></td><td><?= e($a['impact'] ?? '') ?></td><td><?= e($a['made_by'] ?? '') ?><br><span class="muted small"><?= e(fdate($a['made_on'])) ?></span></td><td><?= e($a['approved_by'] ?? '') ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php if ($edit): ?><details><summary><strong><?= e(t('icaap.add_assumption')) ?></strong></summary><form method="post" action="<?= e(url('icaap/' . $c['id'] . '/assumptions')) ?>" class="form-grid" novalidate><?= csrf_field() ?>
<?= ff('text', 'stage', 'icaap.stage', '', ['required' => true, 'hint' => t('icaap.stage_hint')]) ?><?= ff('textarea', 'assumption', 'icaap.assumption', '', ['required' => true, 'wide' => true]) ?><?= ff('textarea', 'rationale', 'icaap.rationale', '', ['wide' => true]) ?>
<?= ff('text', 'impact', 'icaap.impact', '') ?><?= ff('text', 'made_by', 'icaap.made_by', '') ?><?= ff('date', 'made_on', 'icaap.made_on', date('Y-m-d')) ?><?= ff('text', 'approved_by', 'icaap.approved_by', '') ?>
<div class="field"><button class="btn" type="submit"><?= e(t('common.save')) ?></button></div></form></details><?php endif; ?></section>
